// El sobre del evento ya lo valido el enrutador (HT-51 T02, seccion 1): aqui
// solo se comprueba lo unico que usa la consulta, datos.reporte_id. Si falta o
// no es un UUID el nodo falla a proposito: el despachador marca el evento como
// fallido y el reproceso lo reintenta, en lugar de perderlo en silencio.
const evento = $input.first().json;
const reporteId = evento.datos && evento.datos.reporte_id;
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

if (typeof reporteId !== 'string' || !UUID.test(reporteId)) {
  throw new Error('datos.reporte_id ausente o no es un UUID: ' + JSON.stringify(reporteId));
}

return [{ json: { evento_id: evento.id || null, reporte_id: reporteId } }];

// La consulta devuelve una fila por alerta nueva. Con alwaysOutputData, un
// reporte critico sin ciudadanos a menos de 500 m llega aqui como un item
// vacio: el suscriptor responde alertas_creadas = 0, no falla.
const reporteId = $('Validar evento').first().json.reporte_id;
const filas = $input.all()
  .map((i) => i.json)
  .filter((f) => f && f.usuario_id);

return [{
  json: {
    reporte_id: reporteId,
    alertas_creadas: filas.length,
    distancias_m: filas.map((f) => Number(f.distancia_m)),
  },
}];

// El despachador entrega todos los eventos reporte.* (HT-51 T02), pero las
// alertas cercanas solo salen de reporte.creado. Un reporte.estado_cambiado
// termina aqui: el suscriptor responde bien y el evento queda entregado.
const evento = $input.first().json;

return [{
  json: {
    reporte_id: null,
    alertas_creadas: 0,
    motivo: 'tipo_no_aplicable',
    tipo: evento.tipo || null,
  },
}];
